'brasil-colonial':c=>sky('6',c)+sun(70,44,15)+hill(100,'#2d5a47',1,22)+hill(116,'#1f4535',1,14)+`<path d="M250 118V88h60v30z" fill="#efe3c6"/><path d="M244 90L280 66 316 90z" fill="#b5582f"/><rect x="272" y="100" width="16" height="18" fill="#6b3d20"/><path d="M290 70v-16M284 62h12" stroke="#efe3c6" stroke-width="2.5"/>`+[[40,128],[120,124],[350,126],[185,130]].map(([x,y])=>`<path d="M${x} ${y}v-34" stroke="#3b2a17" stroke-width="3"/><path d="M${x} ${y-34}q-22-6-28 8M${x} ${y-34}q22-6 28 8M${x} ${y-34}q-8-16-24-14M${x} ${y-34}q8-16 24-14" stroke="#58a55b" stroke-width="3.5" fill="none" stroke-linecap="round"/>`).join('')+`<path d="M0 140H400V150H0Z" fill="#17352a"/>`,
